for _ in range(int(input())):
	N = int(input())
	A = [int(i) for i in input().split()]
	dict = {}
	ans = 4 * N
	front = 0
	back = 0
	while back < N:
		if A[back] in dict:
			for i in range(front, dict[A[back]]):
				if A[i] in dict:
					del dict[A[i]]
			ans = min(2 * min(front, N - back) + max(front, N - back), ans)
			front = dict[A[back]] + 1
			dict[A[back]] = back
			back += 1
		else:
			dict[A[back]] = back
			back += 1
	ans = min(2 * min(front, N - back) + max(front, N - back), ans)
	print(ans)
